import React, { useEffect, useRef, useState } from 'react';

const RemoteViewer = ({ hostname }) => {
  const canvasRef = useRef(null);
  const [status, setStatus] = useState('Desconectado');
  const wsRef = useRef(null);

  useEffect(() => {
    // 1. Configura la URL del WebSocket (Ajusta la IP de tu servidor si es necesario)
   // const SERVER_IP = window.location.hostname || '127.0.0.1';
   // const wsUrl = `ws://${SERVER_IP}:8006/ws/operator/${hostname}`;
   // const wsUrl = `ws://${SERVER_IP}:8006/api/ws/operator/${hostname}`;

   const SERVER_IP = '172.21.20.14';  // IP fija del servidor Cisa TI
   const wsUrl = `ws://${SERVER_IP}:8006/api/ws/operator/${hostname}`;

    setStatus('Conectando...');
    const ws = new WebSocket(wsUrl);
    wsRef.current = ws;

    ws.onopen = () => {
      setStatus('🟢 Conectado');
      console.log('Conectado al feed de escritorio remoto');
    };

    ws.onmessage = (event) => {
      // 2. Recibe la imagen en Base64 desde FastAPI y la dibuja en el Canvas
      const base64Image = event.data;
      const img = new Image();
      img.src = `data:image/jpeg;base64,${base64Image}`;

      img.onload = () => {
        const canvas = canvasRef.current;
        if (canvas) {
          const ctx = canvas.getContext('2d');
          // Ajusta dinámicamente el tamaño del Canvas al de la imagen recibida
          if (canvas.width !== img.width || canvas.height !== img.height) {
            canvas.width = img.width;
            canvas.height = img.height;
          }
          ctx.drawImage(img, 0, 0);
        }
      };
    };

    ws.onerror = (err) => {
      console.error('Error de WebSocket:', err);
      setStatus('🔴 Error de conexión');
    };

    ws.onclose = () => {
      setStatus('🔴 Desconectado');
    };

    // Limpieza al desmontar el componente
    return () => {
      if (ws) ws.close();
    };
  }, [hostname]);

  return (
    <div style={{ textAlign: 'center', backgroundColor: '#1e1e1e', padding: '15px', borderRadius: '8px' }}>
      <div style={{ marginBottom: '10px', color: '#fff', fontWeight: 'bold' }}>
        Control Remoto: <span style={{ color: '#00bcd4' }}>{hostname}</span> | Estado: {status}
      </div>

      <div style={{ display: 'inline-block', border: '2px solid #333', overflow: 'hidden', borderRadius: '4px' }}>
        <canvas
          ref={canvasRef}
          style={{ cursor: 'crosshair', maxWidth: '100%', height: 'auto', display: 'block' }}
        />
      </div>
    </div>
  );
};

export default RemoteViewer;
